interface User {
  readonly id: number;
  email: string;
  role?: "admin" | "user";
  joinedAt: string;
}

// 1. keyof T — the union of T's property names (all string literals)
type UserKeys = keyof User;   // "id" | "email" | "role" | "joinedAt"

// 2. Indexed access T[K] — the type of one property (look it up!)
type Email = User["email"];           // string
type Role = User["role"];             // "admin" | "user" | undefined
type Values = User[keyof User];       // union of all value types

// 3. typeof (in type position) — the type OF a value
declare const defaultUser: User;
type DefaultUser = typeof defaultUser;   // User — no retyping!

const config = { host: "localhost", port: 8080 };
type Config = typeof config;   // { host: string; port: number } — captured from the value

// Partial<T> — every property optional. THE update-payload type.
type UserUpdate = Partial<User>;
// ≙ { id?: number; email?: string; role?: ...; joinedAt?: string }
function updateUser(id: number, patch: Partial<User>): void { /* ... */ }
updateUser(1, { email: "new@example.com" });   // ✓ any subset

// Required<T> — the inverse: all properties present.
type MandatoryUser = Required<User>;   // role becomes required too

// Pick<T, K> — keep only the listed properties. Views, DTOs, API fields.
type UserCard = Pick<User, "email" | "role">;
// ≙ { email: string; role?: "admin" | "user" }

// Omit<T, K> — remove the listed properties. Secrets, internals.
type PublicUser = Omit<User, "id">;   // ≙ Pick's complement

// Record<K, V> — a dictionary with a fixed key set.
type Roles = Record<"admin" | "editor" | "viewer", string[]>;
// ≙ { admin: string[]; editor: string[]; viewer: string[] }
const perms: Roles = {
  admin: ["read", "write"],
  editor: ["read", "write"],
  viewer: ["read"],
};   // missing any key → compile error. Autocomplete for every key ✓

// ReturnType<F> — the return type of a function.
function loadUser(): Promise<User> { /* ... */ return null as never; }
type Loaded = ReturnType<typeof loadUser>;   // Promise<User>

type T1 = Awaited<Promise<User>>;              // User
type T2 = Awaited<Promise<Promise<User>>>;    // User — recursion handled
type T3 = Awaited<User | Promise<Error>>;     // User | Error — unions too

// Where you'll actually use it — tying an async function's result into another type:
async function fetchUser(): Promise<User> { /* ... */ return null as never; }

async function render() {
  const user: Awaited<ReturnType<typeof fetchUser>> = await fetchUser();
  // verbose but bulletproof — more often you just write: const user = await fetchUser();
  // inference handles it. Awaited shines in generic wrappers:
}

async function cached<T>(fn: () => Promise<T>): Promise<T> {
  // note the .then plumbing keeps T; if you mapped values yourself you'd use
  // Awaited<T> to normalize whatever a chain hands you
  return fn();
}

