interface User {
  readonly id: number;
  email: string;
  passwordHash: string;
  role: "admin" | "user";
  displayName?: string;
}

type PublicUser = Omit<User, "passwordHash">;
type UserPatch = Partial<Pick<User, "email" | "role" | "displayName">;
type RolePerms = Record<User["role"], string[]>;

const rolePerms: RolePerms = {
  admin: ["users:read", "users:write"],
  user: ["users:read"],
};

function sanitize(user: User): PublicUser {
  const { passwordHash, ...rest } = user;
  return rest satisfies PublicUser;   // runtime strip + compile-time proof
}

